from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product
import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        n = len(jobs)
        for mask in range(1 << n):
            if mask.bit_count() != k:
                continue
            chosen = [jobs[i] for i in range(n) if mask >> i & 1]
            ids = {j["id"] for j in chosen}
            if ids & blocked or not mandatory <= ids:
                continue
            counts = {}
            for job in chosen:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(chosen, key=lambda j: (j["start"], j["end"]))
            ends = []
            valid = True
            for job in ordered:
                ends = [end for end in ends if end > job["start"]]
                ends.append(job["end"])
                if len(ends) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            names = sorted(ids)
            value = sum(j["value"] for j in chosen)
            if (best_value is None or value > best_value or
                (value == best_value and
                 (names < best_ids if tie == "smallest" else names > best_ids))):
                best_value, best_ids = value, names
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if ident not in winners or key > winners[ident][0]:
            winners[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(num):
        if mode == "floor":
            return num // 10000
        return (num + 5000) // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        allowed = sorted(row["version"] for row in packages[name]
                         if row["version"] not in blocked.get(name, []) and
                         (name not in pins or row["version"] == pins[name]))
        choices.append([-1] + allowed)
    rows_by_version = {name: {row["version"]: row for row in packages[name]}
                       for name in names}
    best = None
    for vector in product(*choices):
        selected = dict(zip(names, vector))
        if any(selected.get(name, -1) < bounds[0] or
               selected.get(name, -1) > bounds[1]
               for name, bounds in roots.items()):
            continue
        edges = {}
        valid = True
        for name, version in selected.items():
            if version == -1:
                continue
            edges[name] = []
            row = rows_by_version[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = selected.get(target, -1)
                if not dep["min"] <= target_version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue
        reachable = set()
        active = set()
        finished = set()
        cyclic = False

        def visit(name):
            nonlocal cyclic
            if name in active:
                cyclic = True
                return
            if name in finished:
                return
            active.add(name)
            reachable.add(name)
            for child in edges.get(name, []):
                visit(child)
            active.remove(name)
            finished.add(name)

        for root in roots:
            visit(root)
        if cyclic or reachable != {n for n, v in selected.items() if v != -1}:
            continue
        # Product order already follows the required ascending-name vector.
        if best is None or vector < best:
            best = vector
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": {name: version for name, version in zip(names, best)
                         if version != -1}}


def _routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bit.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    start = data["start"]
    queue = [(start, source, initial_mask, data["coupons"])]
    best = {initial: start}
    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if best.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in options:
                reached = depart + duration
                if reached > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                nxt = (next_node, next_mask, left)
                if reached < best.get(nxt, float("inf")):
                    best[nxt] = reached
                    heapq.heappush(queue, (reached, next_node, next_mask, left))
    return {"arrival": None}


SOLVERS = {
    "component_01": _interval_solver(1, "smallest"),
    "component_02": _interval_solver(2, "smallest"),
    "component_03": _interval_solver(1, "largest"),
    "component_04": _interval_solver(2, "largest"),
    "component_05": _interval_solver(1, "smallest"),
    "component_06": _ledger,
    "component_07": _resolver,
    "component_08": _routes,
}
